package com.dorm.fourchess;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import java.io.*;
import java.lang.reflect.*;

/** Real rendered banners, touch, lifecycle, and the same incoming-state path used by every LAN seat. */
public final class AllianceUiProbe extends Instrumentation {
    private final StringBuilder log=new StringBuilder();private MainActivity activity;private FourChessView board;private AllianceAnnouncementView banner;private FactionStripView hud;private Bundle args;
    private void check(boolean ok,String label){if(!ok)throw new AssertionError(label);log.append("PASS ").append(label).append('\n');}
    private Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
    private void set(Object object,String name,Object value)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);f.set(object,value);}
    private void invoke(String name,Class<?>[] types,Object... values)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(activity,values);}
    private interface Task{void run()throws Exception;}
    private void main(Task task)throws Exception{final Throwable[] error={null};runOnMainSync(()->{try{task.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
    private void fresh()throws Exception{invoke("startMatch",new Class<?>[]{String[].class},(Object)new String[]{"红方棋友","绿方棋友","蓝方棋友","金方棋友"});}
    private void request(int actor,int action,int target)throws Exception{invoke("requestDiplomacy",new Class<?>[]{int.class,int.class,int.class},actor,action,target);}
    private void pact(int a,int b)throws Exception{request(a,0,b);request(b,1,a);}
    private void layout(){Rect visible=new Rect();check(banner.getGlobalVisibleRect(visible)&&visible.width()==banner.getWidth()&&visible.height()==banner.getHeight(),"banner fully inside safe measured viewport");check(banner.getTop()>=hud.getTop()&&banner.getBottom()<=hud.getBottom(),"banner stays within top HUD without covering board");check(banner.getBottom()<=board.getTop(),"all chess touch points remain below banner");check(!banner.isClickable()&&!banner.isFocusable(),"notice is non-interactive");}
    private void tap(float x,float y){long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,x,y,0),up=MotionEvent.obtain(now,now+40,MotionEvent.ACTION_UP,x,y,0);board.dispatchTouchEvent(down);board.dispatchTouchEvent(up);down.recycle();up.recycle();}
    private void shot(String name)throws Exception{SystemClock.sleep(200);Bitmap image=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"alliance-"+name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private void local()throws Exception{
        main(()->{fresh();String before=board.exportState();request(0,0,1);check(banner.activePair()==0&&hud.marksForOwner(0)==0,"invitation alone has no banner or mark");request(1,2,0);check(banner.activePair()==0,"declining does not announce alliance");pact(0,1);check(board.allied(0,1),"real accept still establishes treaty");});SystemClock.sleep(450);
        main(()->{check(banner.activePair()==1&&banner.isShown(),"accepted treaty presents four-second dual-portrait banner");layout();check(banner.getContentDescription().toString().contains("红方棋友")&&banner.getContentDescription().toString().contains("绿方棋友"),"notice uses actual nicknames and accessible alliance status");check(hud.marksForOwner(0)==1&&hud.marksForOwner(1)==1&&board.allianceMarks(0)==1&&board.allianceMarks(1)==1,"allied avatars and both armies share same seal");check(hud.marksForOwner(2)==0&&board.allianceMarks(3)==0,"unrelated armies carry no treaty seal");String state=board.exportState();Bitmap image=Bitmap.createBitmap(board.getWidth(),board.getHeight(),Bitmap.Config.ARGB_8888);board.draw(new Canvas(image));image.recycle();check(state.equals(board.exportState()),"drawing seals leaves all chess data unchanged");
            float cell=((Number)field(board,"cellX")).floatValue(),x=((Number)field(board,"ox")).floatValue(),y=((Number)field(board,"oy")).floatValue();tap(x+5*cell,y+15*cell);tap(x+5*cell,y+14*cell);check(board.currentTurn()==1,"real touch selection and move work during announcement");});shot("accepted");
        int original="landscape".equals(args.getString("orientation","portrait"))?0:1;main(()->activity.setRequestedOrientation(original==0?1:0));SystemClock.sleep(600);main(()->{layout();check(banner.activePair()==1,"rotation retains same live announcement");});shot("rotated");main(()->activity.setRequestedOrientation(original));SystemClock.sleep(600);
        SystemClock.sleep(4300);main(()->{check(banner.activePair()==0&&banner.getVisibility()!=View.VISIBLE,"notice automatically dismisses after a few seconds");check(hud.marksForOwner(0)==1&&board.allianceMarks(1)==1,"avatar and army seals persist after notice dismisses");});shot("persistent");
        main(()->{pact(0,2);pact(2,3);check(banner.activePair()==2&&banner.pendingCount()==1,"consecutive treaties queue instead of overwriting");check(board.allianceMarks(0)==3&&board.allianceMarks(1)==1&&board.allianceMarks(2)==34&&board.allianceMarks(3)==32,"different pair IDs remain distinct with multiple treaties");});shot("multiple");
        main(()->{request(0,3,2);check(banner.activePair()==32&&board.allianceMarks(0)==1&&hud.marksForOwner(2)==32,"break removes only corresponding marks and skips invalid queued notice");request(3,4,1);check(banner.activePair()==0&&hud.marksForOwner(3)==0&&board.allianceMarks(2)==0,"surrender clears withdrawn player's seals and obsolete notice");});
        main(()->{fresh();invoke("showMatchMenu",new Class<?>[0]);});SystemClock.sleep(200);
        main(()->{activity.onHostDiplomacy(0,0,1);activity.onHostDiplomacy(1,1,0);check(banner.activePair()==0&&banner.pendingCount()==1,"host accepts while dialog open and queues visible notice");AlertDialog dialog=(AlertDialog)field(activity,"diplomacyDialog");dialog.getButton(-2).performClick();});SystemClock.sleep(400);
        main(()->{check(banner.activePair()==1,"notice begins when dialog closes and focus returns");request(0,3,1);check(banner.activePair()==0&&hud.marksForOwner(1)==0,"broken treaty immediately removes visual state");});
    }
    private void incoming()throws Exception{
        final String[] states=new String[4];main(()->{FourChessView remote=new FourChessView(getTargetContext());remote.setSoundEnabled(false);states[0]=remote.exportState();remote.tryDiplomacy(0,0,1);states[1]=remote.exportState();remote.tryDiplomacy(1,1,0);states[2]=remote.exportState();remote.tryNetworkMove(0,5,15,5,14);states[3]=remote.exportState();});
        for(int seat=0;seat<4;seat++){final int owner=seat;main(()->{fresh();board.setLocalPlayer(owner);set(activity,"receivedNetworkState",false);activity.onState(states[0]);activity.onState(states[1]);check(banner.activePair()==0,"LAN seat sees no announcement for pending offer "+owner);activity.onState(states[2]);check(banner.activePair()==1&&board.allianceMarks(0)==1&&hud.marksForOwner(1)==1,"incoming acceptance reaches every seat including spectators "+owner);long started=(Long)field(banner,"started");activity.onState(states[2]);activity.onState(states[3]);check((Long)field(banner,"started")==started&&banner.pendingCount()==0,"duplicate and subsequent move states do not replay announcement "+owner);});}
        main(()->{fresh();set(activity,"receivedNetworkState",false);activity.onState(states[2]);check(banner.activePair()==0&&board.allianceMarks(0)==1,"joining an existing treaty displays seals without replaying historical ceremony");fresh();pact(0,1);invoke("showModePage",new Class<?>[0]);check(banner.activePair()==0&&banner.pendingCount()==0,"leaving game page cancels notice and pending callbacks");pact(2,3);check(banner.activePair()==0&&banner.pendingCount()==1,"acceptance while mode page open waits for battle HUD");invoke("hideModePage",new Class<?>[0]);check(banner.activePair()==32,"returning from internal mode page resumes queued ceremony");});
    }
    @Override public void onCreate(Bundle arguments){super.onCreate(arguments);args=arguments==null?new Bundle():arguments;start();}
    @Override public void onStart(){Bundle result=new Bundle();try{activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();main(()->activity.setRequestedOrientation("landscape".equals(args.getString("orientation","portrait"))?0:1));SystemClock.sleep(600);main(()->{board=(FourChessView)field(activity,"board");banner=(AllianceAnnouncementView)field(activity,"allianceAnnouncement");hud=(FactionStripView)field(activity,"playerStrip");board.setSoundEnabled(false);});local();incoming();log.append("ALLIANCE UI COMPLETE\n");result.putString("stream",log.toString());main(()->activity.finish());finish(Activity.RESULT_OK,result);}catch(Throwable error){result.putString("stream",log+"FAIL "+android.util.Log.getStackTraceString(error));if(activity!=null)try{main(()->activity.finish());}catch(Exception ignored){}finish(Activity.RESULT_CANCELED,result);}}
}
